`timescale 1ns / 1ps

module bram #(
    parameter WORDS = 8192,             // 32 KB = 8192 từ 32-bit (32768 byte)
    parameter INIT_FILE = ""
) (
    input  wire        clk,
    input  wire        resetn,
    input  wire        mem_valid,
    input  wire [31:0] mem_addr,
    input  wire [31:0] mem_wdata,
    input  wire [3:0]  mem_wstrb,
    output reg         mem_ready,
    output reg  [31:0] mem_rdata
);

    // Mảng bộ nhớ 32 KB
    reg [31:0] mem [0:WORDS-1];
    wire [12:0] word_addr = mem_addr[14:2];

    initial begin
        if (INIT_FILE != "") begin
            $readmemh(INIT_FILE, mem);
        end
    end

    always @(posedge clk) begin
        if (!resetn) begin
            mem_ready <= 1'b0;
            mem_rdata <= 32'd0;
        end else begin
            mem_ready <= 1'b0;
            if (mem_valid && !mem_ready) begin
                mem_ready <= 1'b1;
                mem_rdata <= mem[word_addr];
                if (mem_wstrb[0]) mem[word_addr][ 7: 0] <= mem_wdata[ 7: 0];
                if (mem_wstrb[1]) mem[word_addr][15: 8] <= mem_wdata[15: 8];
                if (mem_wstrb[2]) mem[word_addr][23:16] <= mem_wdata[23:16];
                if (mem_wstrb[3]) mem[word_addr][31:24] <= mem_wdata[31:24];
            end
        end
    end

endmodule

`timescale 1ns / 1ps

module uart_tx #(
    parameter CLK_FREQ  = 27000000,
    parameter BAUD_RATE = 115200
) (
    input  wire       clk,
    input  wire       resetn,
    input  wire       tx_start,
    input  wire [7:0] tx_data,
    output reg        tx,
    output wire       busy
);

    localparam integer CLK_DIV = CLK_FREQ / BAUD_RATE; // 27000000 / 115200 ≈ 234

    localparam [1:0]
        STATE_IDLE  = 2'd0,
        STATE_START = 2'd1,
        STATE_DATA  = 2'd2,
        STATE_STOP  = 2'd3;

    reg [1:0]  state;
    reg [15:0] baud_cnt;
    reg [2:0]  bit_cnt;
    reg [7:0]  shift_reg;

    assign busy = (state != STATE_IDLE);

    always @(posedge clk) begin
        if (!resetn) begin
            state     <= STATE_IDLE;
            baud_cnt  <= 16'd0;
            bit_cnt   <= 3'd0;
            shift_reg <= 8'd0;
            tx        <= 1'b1;
        end else begin
            case (state)
                STATE_IDLE: begin
                    tx       <= 1'b1;
                    baud_cnt <= 16'd0;
                    bit_cnt  <= 3'd0;
                    if (tx_start) begin
                        shift_reg <= tx_data;
                        state     <= STATE_START;
                    end
                end

                STATE_START: begin
                    tx <= 1'b0; // start bit
                    if (baud_cnt == CLK_DIV - 1) begin
                        baud_cnt <= 16'd0;
                        state    <= STATE_DATA;
                    end else begin
                        baud_cnt <= baud_cnt + 1'b1;
                    end
                end

                STATE_DATA: begin
                    tx <= shift_reg[0];
                    if (baud_cnt == CLK_DIV - 1) begin
                        baud_cnt  <= 16'd0;
                        shift_reg <= {1'b0, shift_reg[7:1]};
                        if (bit_cnt == 3'd7) begin
                            state <= STATE_STOP;
                        end else begin
                            bit_cnt <= bit_cnt + 1'b1;
                        end
                    end else begin
                        baud_cnt <= baud_cnt + 1'b1;
                    end
                end

                STATE_STOP: begin
                    tx <= 1'b1; // stop bit
                    if (baud_cnt == CLK_DIV - 1) begin
                        baud_cnt <= 16'd0;
                        state    <= STATE_IDLE;
                    end else begin
                        baud_cnt <= baud_cnt + 1'b1;
                    end
                end

                default: begin
                    state <= STATE_IDLE;
                end
            endcase
        end
    end

endmodule

`timescale 1ns / 1ps

module soc_top (
    input  wire       clk_27m,      // Thạch anh 27 MHz (PIN 4)
    input  wire       btn_s1,       // Nút S1 (PIN 88, Active-Low)
    output wire       uart_tx_pin,  // UART TX nối BL616 (PIN 69)
    output wire [5:0] led           // 6 LED trên bo (PIN 15..20, Active-Low)
);

    // -------------------------------------------------------------
    // 1. Mạch tạo tín hiệu Reset
    //    Giữ reset 16 chu kỳ sau cấp nguồn hoặc khi nhấn S1
    // -------------------------------------------------------------
    reg [4:0] por_cnt = 5'd0;
    reg       sys_resetn = 1'b0;

    always @(posedge clk_27m) begin
        if (!btn_s1) begin
            por_cnt    <= 5'd0;
            sys_resetn <= 1'b0;
        end else if (por_cnt < 5'd16) begin
            por_cnt    <= por_cnt + 1'b1;
            sys_resetn <= 1'b0;
        end else begin
            sys_resetn <= 1'b1;
        end
    end

    // -------------------------------------------------------------
    // 2. Tín hiệu bus bộ nhớ của PicoRV32
    // -------------------------------------------------------------
    wire        mem_valid;
    wire        mem_instr;
    wire        mem_ready;
    wire [31:0] mem_addr;
    wire [31:0] mem_wdata;
    wire [3:0]  mem_wstrb;
    wire [31:0] mem_rdata;

    // -------------------------------------------------------------
    // 3. PicoRV32 CPU Core
    // -------------------------------------------------------------
    picorv32 #(
        .ENABLE_COUNTERS   (1),
        .ENABLE_COUNTERS64 (1),
        .ENABLE_MUL        (0),
        .ENABLE_DIV        (0),
        .ENABLE_FAST_MUL   (0),
        .ENABLE_PCPI       (0),
        .COMPRESSED_ISA    (0),
        .PROGADDR_RESET    (32'h0000_0000),
        .STACKADDR         (32'h0000_8000) // Đỉnh BRAM 32 KB
    ) cpu (
        .clk         (clk_27m),
        .resetn      (sys_resetn),
        .trap        (),
        .mem_valid   (mem_valid),
        .mem_instr   (mem_instr),
        .mem_ready   (mem_ready),
        .mem_addr    (mem_addr),
        .mem_wdata   (mem_wdata),
        .mem_wstrb   (mem_wstrb),
        .mem_rdata   (mem_rdata),
        .mem_la_read (),
        .mem_la_write(),
        .mem_la_addr (),
        .mem_la_wdata(),
        .mem_la_wstrb(),
        .pcpi_valid  (),
        .pcpi_insn   (),
        .pcpi_rs1    (),
        .pcpi_rs2    (),
        .pcpi_wr     (1'b0),
        .pcpi_rd     (32'd0),
        .pcpi_wait   (1'b0),
        .pcpi_ready  (1'b0),
        .irq         (32'd0),
        .eoi         (),
        .trace_valid (),
        .trace_data  ()
    );

    // -------------------------------------------------------------
    // 4. Giải mã địa chỉ (Memory-mapped IO)
    //    0x0000_0000 - 0x0000_7FFF: BRAM 32 KB
    //    0x1000_0000: UART TX (ghi byte)
    //    0x1000_0004: UART STATUS (bit 0 = bận)
    //    0x2000_0000: LED (6 bit thấp)
    // -------------------------------------------------------------
    wire sel_bram        = (mem_addr[31:15] == 17'd0);
    wire sel_uart        = (mem_addr[31:28] == 4'h1);
    wire sel_uart_tx     = sel_uart && (mem_addr[7:0] == 8'h00);
    wire sel_uart_status = sel_uart && (mem_addr[7:0] == 8'h04);
    wire sel_led         = (mem_addr[31:28] == 4'h2);
    wire sel_invalid     = !(sel_bram || sel_uart || sel_led);

    // -------------------------------------------------------------
    // 5. Khối BRAM (32 KB)
    // -------------------------------------------------------------
    wire        bram_ready;
    wire [31:0] bram_rdata;
    wire        bram_valid = mem_valid && sel_bram;

    bram #(
        .WORDS     (8192),
        .INIT_FILE ("")
    ) ram (
        .clk       (clk_27m),
        .resetn    (sys_resetn),
        .mem_valid (bram_valid),
        .mem_addr  (mem_addr),
        .mem_wdata (mem_wdata),
        .mem_wstrb (mem_wstrb),
        .mem_ready (bram_ready),
        .mem_rdata (bram_rdata)
    );

    // -------------------------------------------------------------
    // 6. Khối UART TX
    // -------------------------------------------------------------
    reg        uart_ready;
    reg        uart_tx_start;
    reg [7:0]  uart_tx_data;
    wire       uart_busy;

    uart_tx #(
        .CLK_FREQ  (27000000),
        .BAUD_RATE (115200)
    ) u_uart_tx (
        .clk      (clk_27m),
        .resetn   (sys_resetn),
        .tx_start (uart_tx_start),
        .tx_data  (uart_tx_data),
        .tx       (uart_tx_pin),
        .busy     (uart_busy)
    );

    always @(posedge clk_27m) begin
        if (!sys_resetn) begin
            uart_ready    <= 1'b0;
            uart_tx_start <= 1'b0;
            uart_tx_data  <= 8'd0;
        end else begin
            uart_tx_start <= 1'b0;
            uart_ready    <= 1'b0;
            if (mem_valid && sel_uart && !uart_ready) begin
                uart_ready <= 1'b1;
                if (sel_uart_tx && |mem_wstrb) begin
                    uart_tx_data  <= mem_wdata[7:0];
                    uart_tx_start <= 1'b1;
                end
            end
        end
    end

    // -------------------------------------------------------------
    // 7. Khối điều khiển LED
    // -------------------------------------------------------------
    reg [5:0] led_reg;
    reg       led_ready;

    always @(posedge clk_27m) begin
        if (!sys_resetn) begin
            led_reg   <= 6'd0;
            led_ready <= 1'b0;
        end else begin
            led_ready <= 1'b0;
            if (mem_valid && sel_led && !led_ready) begin
                led_ready <= 1'b1;
                if (|mem_wstrb) begin
                    led_reg <= mem_wdata[5:0];
                end
            end
        end
    end

    // LED trên Tang Nano 20K tích cực thấp (Active-Low: 0 sáng, 1 tắt)
    assign led = ~led_reg;

    // -------------------------------------------------------------
    // 8. Xử lý địa chỉ không hợp lệ (không treo CPU)
    // -------------------------------------------------------------
    reg invalid_ready;

    always @(posedge clk_27m) begin
        if (!sys_resetn) begin
            invalid_ready <= 1'b0;
        end else begin
            invalid_ready <= 1'b0;
            if (mem_valid && sel_invalid && !invalid_ready) begin
                invalid_ready <= 1'b1;
            end
        end
    end

    // -------------------------------------------------------------
    // 9. Ghép nối tín hiệu bus phản hồi về CPU
    // -------------------------------------------------------------
    assign mem_ready = (sel_bram)    ? bram_ready :
                       (sel_uart)    ? uart_ready :
                       (sel_led)     ? led_ready :
                                       invalid_ready;

    assign mem_rdata = (sel_bram)        ? bram_rdata :
                       (sel_uart_status) ? {31'd0, uart_busy} :
                       (sel_led)         ? {26'd0, led_reg} :
                                           32'd0;

endmodule

/* Linker script cho PicoRV32 SoC trên Tang Nano 20K (BRAM 32 KB) */
ENTRY(_start)

MEMORY
{
    BRAM (rwx) : ORIGIN = 0x00000000, LENGTH = 32K
}

SECTIONS
{
    . = 0x00000000;

    .init : {
        KEEP(*(.init))
        KEEP(*(.init.*))
    } > BRAM

    .text : {
        . = ALIGN(4);
        *(.text)
        *(.text.*)
    } > BRAM

    .rodata : {
        . = ALIGN(4);
        *(.rodata)
        *(.rodata.*)
        *(.srodata)
        *(.srodata.*)
    } > BRAM

    .data : {
        . = ALIGN(4);
        _sdata = .;
        *(.data)
        *(.data.*)
        *(.sdata)
        *(.sdata.*)
        . = ALIGN(4);
        _edata = .;
    } > BRAM

    .bss : {
        . = ALIGN(4);
        _sbss = .;
        *(.bss)
        *(.bss.*)
        *(.sbss)
        *(.sbss.*)
        *(COMMON)
        . = ALIGN(4);
        _ebss = .;
    } > BRAM

    . = ALIGN(4);
    _end = .;

    __stack_top = ORIGIN(BRAM) + LENGTH(BRAM);
}

#include <stdint.h>

#define UART_TX_REG     (*(volatile uint32_t *)0x10000000)
#define UART_STATUS_REG (*(volatile uint32_t *)0x10000004)
#define LED_REG         (*(volatile uint32_t *)0x20000000)

#ifdef SIM
#define CYCLES_PER_SEC 1000U
#else
#define CYCLES_PER_SEC 27000000U
#endif

static inline uint32_t get_cycle(void) {
    uint32_t c;
    __asm__ volatile ("rdcycle %0" : "=r"(c));
    return c;
}

static void uart_putc(char c) {
    while (UART_STATUS_REG & 1) {
        /* Chờ bit bận ở UART_STATUS hạ xuống */
    }
    UART_TX_REG = (uint32_t)(uint8_t)c;
}

static void uart_puts(const char *s) {
    while (*s) {
        uart_putc(*s++);
    }
}

static uint32_t divmod10(uint32_t n, uint32_t *r) {
    uint32_t q = 0;
    uint32_t rem = 0;
    for (int i = 31; i >= 0; i--) {
        rem = (rem << 1) | ((n >> i) & 1);
        if (rem >= 10) {
            rem -= 10;
            q |= (1U << i);
        }
    }
    if (r) *r = rem;
    return q;
}

static void uart_put_num(uint32_t val) {
    char buf[11];
    int idx = 0;
    if (val == 0) {
        uart_putc('0');
        return;
    }
    while (val > 0) {
        uint32_t rem = 0;
        val = divmod10(val, &rem);
        buf[idx++] = (char)('0' + rem);
    }
    while (idx > 0) {
        uart_putc(buf[--idx]);
    }
}

int main(void) {
    uint32_t led_state = 0;
    LED_REG = led_state;

    while (1) {
        uint32_t cycle = get_cycle();
        uart_puts("Hello from PicoRV32 on Tang Nano 20K, cycle=");
        uart_put_num(cycle);
        uart_puts("\r\n");

        /* Đảo 1 LED */
        led_state ^= 1;
        LED_REG = led_state;

        /* Chờ 1 giây theo chu kỳ clock */
        uint32_t start = get_cycle();
        while ((get_cycle() - start) < CYCLES_PER_SEC) {
            /* chờ */
        }
    }

    return 0;
}

