                #(BIT_PERIOD_NS); rx_byte[2] = uart_tx_pin;
                #(BIT_PERIOD_NS); rx_byte[3] = uart_tx_pin;
                #(BIT_PERIOD_NS); rx_byte[4] = uart_tx_pin;
                #(BIT_PERIOD_NS); rx_byte[5] = uart_tx_pin;
                #(BIT_PERIOD_NS); rx_byte[6] = uart_tx_pin;
